<?php require __DIR__.'/ui.php';role(['admin','gerente','caixa']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO accounts_payable(description,category,cost_center,amount,due_date,recurring)VALUES(?,?,?,?,?,?)")->execute([$_POST['description'],$_POST['category'],$_POST['cost_center'],$_POST['amount'],$_POST['due_date'],isset($_POST['recurring'])?1:0]);go('payables.php');}if(isset($_GET['pay'])){$p->prepare("UPDATE accounts_payable SET status='Pago',paid_at=CURRENT_TIMESTAMP WHERE id=?")->execute([(int)$_GET['pay']]);go('payables.php');}$rows=$p->query("SELECT * FROM accounts_payable ORDER BY status,due_date")->fetchAll();page_head('Contas a pagar');?><div class="grid g2"><div class="card"><form method="post"><?=csrf_field()?><label>Descrição</label><input name="description" required><label>Categoria</label><input name="category"><label>Centro de custo</label><input name="cost_center"><label>Valor</label><input type="number" step=".01" name="amount"><label>Vencimento</label><input type="date" name="due_date"><label><input style="width:auto" type="checkbox" name="recurring"> Recorrente</label><button class="primary">Adicionar</button></form></div><div class="card"><table><tr><th>Descrição</th><th>Vencimento</th><th>Valor</th><th>Status</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['description'])?></td><td><?=$x['due_date']?></td><td><?=money($x['amount'])?></td><td><?=$x['status']?> <?php if($x['status']!=='Pago'):?><a href="?pay=<?=$x['id']?>">Pagar</a><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>